  run(False);ref=data();run(True);assert all(np.array_equal(a,b) for a,b in zip(ref,data()))
  timings={False:[],True:[]}
  for rep in range(110):
   for arm in ((False,True) if rep%2 else (True,False)):
    rt.device_synchronize();t=time.perf_counter();run(arm);rt.device_synchronize();dt=(time.perf_counter()-t)*1e6
    if rep>=10:timings[arm].append(dt)
  row={'rows':rows,'exact':True,'samples_us':{str(k):v for k,v in timings.items()},'median_us':{str(k):statistics.median(v) for k,v in timings.items()}};out['cases'].append(row);print(rows,row['median_us'],flush=True)
